node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Search for the exact product ID
let row = db.prepare(\"SELECT * FROM products WHERE product_id = ?\").get('PROD-B98D14');
if (!row) {
  // Try partial match
  row = db.prepare(\"SELECT * FROM products WHERE product_id LIKE ?\").get('%B98D14%');
}
if (!row) {
  // Search all tables for this ID
  console.log('Product not found. Searching all product IDs...');
  const all = db.prepare(\"SELECT product_id, name FROM products\").all();
  const match = all.find(r => r.product_id.includes('B98D14') || r.product_id.includes('b98d14'));
  if (match) {
    console.log('Found partial match:', JSON.stringify(match));
  } else {
    console.log('No product with ID PROD-B98D14 exists in the database.');
    console.log('Available product IDs are all numeric. Here are the first few:');
    all.slice(0, 5).forEach(r => console.log('  ' + r.product_id + ' - ' + r.name));
    console.log('  ... (' + all.length + ' total)');
  }
} else {
  console.log('Product found:', JSON.stringify(row, null, 2));
  // Get variants
  const variants = db.prepare(\"SELECT * FROM rt_variants WHERE product_id = ?\").all(row.product_id);
  console.log('Variants:', JSON.stringify(variants, null, 2));
}
db.close();
"

